import SwiftSSLCore
import XCTest

@testable import SwiftSSLCrypto

final class RSAPSSTests: XCTestCase {
    func testSHA256PSSVerificationAndMutation() throws {
        let modulus = bytes(
            ""
        )
        let digest = bytes("29AEB90FADDF4D7ECE03FA92CFFB85213640FC5ED228181BD7BDE889FF3E7A5E")
        let signature = bytes(
            ""
        )
        let key = try RSAPublicKey(modulus: modulus.span, exponent: 65_537)
        XCTAssertTrue(try RSAPSS.verify(
            signature: signature.span,
            messageHash: digest.span,
            publicKey: key,
            hash: .sha256,
            saltLength: 32
        ))

        var mutated = signature
        mutated[mutated.count - 1] ^= 1
        XCTAssertFalse(try RSAPSS.verify(
            signature: mutated.span,
            messageHash: digest.span,
            publicKey: key,
            hash: .sha256,
            saltLength: 32
        ))
    }

    func testSHA384AndSHA512PSSVerification() throws {
        let modulus = bytes(
            ""
        )
        let sha384Digest = bytes("FAD790053DFFC263A8BC39A48D1AABC8D1A3B245CFFB91F27D3F07F7275139DAA6A093E3FC1F863B74C87B80EBD550DC")
        let sha384Signature = bytes(
            ""
        )
        let sha512Digest = bytes("C6BB67619D83A9CA62CB854F8E895C858AE80C6A846A4E93DDEE64A52255DC6A254843CDA8F00B446790DC4FED078F92DD0E943817C819ABE99C9344320D9E61")
        let sha512Signature = bytes(
            "79496484C1BFDD2726054D2CDABC0DDBCE5732720364B8C08C2C56B6D6E355D356FAB726C809C709CC4629F6A7E6A859554FA3E844A9595193257E98F6FBB D102DFF826047796194D2D4DBA65F94F22141F43C116614C7C1BC669A5D6021ECD70C3F0EC6E01C550863B19EB81DC2FB43C162E9CC5FA5789BDD9DA78DFF81C349A1D4BCF451A5D84530DC95D3EAD452AC03893684DECB3A3B422BBA433736E1CEB92E3391B334CB63AA3DA75D8656DEBEEE A0BF7EBC698D09DAE42455494E4437BE051525F9B9012DECEE4DD4E2704F13E639DCE6E60266676E0E9DB52227BA72DD85CC009F02CE31C116DC7E79CDF1D3380DD9F9DCBFD09E6952853E43930F46".replacing(" ", with: "")
        )
        let key = try RSAPublicKey(modulus: modulus.span, exponent: 65_537)
        XCTAssertTrue(try RSAPSS.verify(signature: sha384Signature.span, messageHash: sha384Digest.span, publicKey: key, hash: .sha384, saltLength: 48))
        XCTAssertTrue(try RSAPSS.verify(signature: sha512Signature.span, messageHash: sha512Digest.span, publicKey: key, hash: .sha512, saltLength: 64))
    }

    private func bytes(_ value: String) -> ContiguousArray<UInt8> {
        var result = ContiguousArray<UInt8>()
        var index = value.startIndex
        while index < value.endIndex {
            let next = value.index(index, offsetBy: 2)
            result.append(UInt8(value[index..<next], radix: 16)!)
            index = next
        }
        return result
    }
}
